@ViewEntity({
  name: 'routing_rule_latest_versions',
  schema: 'manual_review_tool',
  synchronize: false,
  expression:
    'SELECT routing_rule_versions.id AS routing_rule_id,\n    to_char((routing_rule_versions.version AT TIME ZONE \'UTC\'::text), \'YYYY-MM-DD"T"HH24:MI:SS.US"Z"\'::text) AS version\n   FROM manual_review_tool.routing_rule_versions\n  WHERE routing_rule_versions.is_current = true;',
})
export class RoutingRuleLatestVersionsView {
  @ViewColumn({ name: 'routing_rule_id' })
  routing_rule_id!: string | null;

  @ViewColumn({ name: 'version' })
  version!: string | null;
}

@ViewEntity({
  name: 'routing_rule_versions',
  schema: 'manual_review_tool',
  materialized: true,
  synchronize: false,
  expression:
    'WITH routing_rule_versions AS (\n         SELECT routing_rules.id,\n            routing_rules.name,\n            routing_rules.org_id,\n            routing_rules.description,\n            routing_rules.status,\n            routing_rules.creator_id,\n            routing_rules.condition_set,\n            routing_rules.sequence_number,\n            routing_rules.destination_queue_id,\n            routing_rules.sys_period\n           FROM manual_review_tool.routing_rules\n        UNION ALL\n         SELECT routing_rule_history.id,\n            routing_rule_history.name,\n            routing_rule_history.org_id,\n            routing_rule_history.description,\n            routing_rule_history.status,\n            routing_rule_history.creator_id,\n            routing_rule_history.condition_set,\n            routing_rule_history.sequence_number,\n            routing_rule_history.destination_queue_id,\n            routing_rule_history.sys_period\n           FROM manual_review_tool.routing_rule_history\n        ), routing_rules_max_period_starts AS (\n         SELECT routing_rule_versions_1.id,\n            max(lower(routing_rule_versions_1.sys_period)) AS max_period_start\n           FROM routing_rule_versions routing_rule_versions_1\n          GROUP BY routing_rule_versions_1.id\n        )\n SELECT routing_rule_versions.id,\n    routing_rule_versions.name,\n    routing_rule_versions.org_id,\n    routing_rule_versions.description,\n    routing_rule_versions.status,\n    routing_rule_versions.creator_id,\n    routing_rule_versions.condition_set,\n    routing_rule_versions.sequence_number,\n    routing_rule_versions.destination_queue_id,\n    lower(routing_rule_versions.sys_period) AS version,\n    routing_rules_max_period_starts.max_period_start = lower(routing_rule_versions.sys_period) AND upper_inf(routing_rule_versions.sys_period) AS is_current\n   FROM routing_rule_versions\n     JOIN routing_rules_max_period_starts ON routing_rules_max_period_starts.id::text = routing_rule_versions.id::text;',
})
export class RoutingRuleVersionsView {
  @ViewColumn({ name: 'id' })
  id!: string | null;

  @ViewColumn({ name: 'name' })
  name!: string | null;

  @ViewColumn({ name: 'org_id' })
  org_id!: string | null;

  @ViewColumn({ name: 'description' })
  description!: string | null;

  @ViewColumn({ name: 'status' })
  status!: RoutingRuleStatus | null;

  @ViewColumn({ name: 'creator_id' })
  creator_id!: string | null;

  @ViewColumn({ name: 'condition_set' })
  condition_set!: unknown | null;

  @ViewColumn({ name: 'sequence_number' })
  sequence_number!: number | null;

  @ViewColumn({ name: 'destination_queue_id' })
  destination_queue_id!: string | null;

  @ViewColumn({ name: 'version' })
  version!: Date | null;

  @ViewColumn({ name: 'is_current' })
  is_current!: boolean | null;
}

